        type="button"
        data-test="account-disconnect"
        :disabled="props.busy !== null || props.transitioning"
        @click="emit('disconnect')"
      >
        {{ props.status.connection === 'authenticating' ? 'Cancel sign-in' : 'Disconnect' }}
